CREATE TABLE public.course_examples (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), course_id text NOT NULL REFERENCES public.courses(id) ON DELETE CASCADE, title text NOT NULL CHECK (char_length(btrim(title)) BETWEEN 1 AND 160), description text NOT NULL DEFAULT '' CHECK (char_length(description)<=2000), media_path text NOT NULL, media_type text NOT NULL CHECK (media_type IN ('image','video')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.course_examples TO anon, authenticated;
GRANT INSERT, UPDATE, DELETE ON public.course_examples TO authenticated;
GRANT ALL ON public.course_examples TO service_role;
ALTER TABLE public.course_examples ENABLE ROW LEVEL SECURITY;
CREATE POLICY "examples public read" ON public.course_examples FOR SELECT TO anon,authenticated USING (true);
CREATE POLICY "examples admin write" ON public.course_examples FOR ALL TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'admin'));
CREATE TABLE public.work_submissions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id), course_id text NOT NULL REFERENCES public.courses(id) ON DELETE CASCADE, title text NOT NULL CHECK (char_length(btrim(title)) BETWEEN 1 AND 160), description text NOT NULL DEFAULT '' CHECK (char_length(description)<=2000), media_path text, media_type text CHECK (media_type IN ('image','video')), work_url text CHECK (work_url IS NULL OR (work_url LIKE 'https://%' AND char_length(work_url)<=2000)), created_at timestamptz NOT NULL DEFAULT now(), CHECK (media_path IS NOT NULL OR work_url IS NOT NULL), CHECK (media_path IS NULL OR media_path LIKE user_id::text || '/%'));
GRANT SELECT, INSERT, DELETE ON public.work_submissions TO authenticated;
GRANT ALL ON public.work_submissions TO service_role;
ALTER TABLE public.work_submissions ENABLE ROW LEVEL SECURITY;
CREATE POLICY "submissions own or admin read" ON public.work_submissions FOR SELECT TO authenticated USING (user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY "submissions enrolled insert" ON public.work_submissions FOR INSERT TO authenticated WITH CHECK (user_id=auth.uid() AND EXISTS (SELECT 1 FROM public.courses c WHERE c.id=course_id AND (NOT c.premium OR EXISTS (SELECT 1 FROM public.purchases p WHERE p.course_id=c.id AND p.user_id=auth.uid()) OR public.has_role(auth.uid(),'admin'))));
CREATE POLICY "submissions own delete" ON public.work_submissions FOR DELETE TO authenticated USING (user_id=auth.uid());
CREATE TABLE public.work_feedback (submission_id uuid PRIMARY KEY REFERENCES public.work_submissions(id) ON DELETE CASCADE, admin_id uuid NOT NULL, status text NOT NULL DEFAULT 'reviewed' CHECK (status IN ('reviewed','revision')), comment text NOT NULL CHECK (char_length(btrim(comment)) BETWEEN 1 AND 2000), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON public.work_feedback TO authenticated;
GRANT ALL ON public.work_feedback TO service_role;
ALTER TABLE public.work_feedback ENABLE ROW LEVEL SECURITY;
CREATE POLICY "feedback owner or admin read" ON public.work_feedback FOR SELECT TO authenticated USING (public.has_role(auth.uid(),'admin') OR EXISTS (SELECT 1 FROM public.work_submissions s WHERE s.id=submission_id AND s.user_id=auth.uid()));
CREATE POLICY "feedback admin insert" ON public.work_feedback FOR INSERT TO authenticated WITH CHECK (admin_id=auth.uid() AND public.has_role(auth.uid(),'admin'));
CREATE POLICY "feedback admin update" ON public.work_feedback FOR UPDATE TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK (admin_id=auth.uid() AND public.has_role(auth.uid(),'admin'));
CREATE TABLE public.site_reviews (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL UNIQUE REFERENCES public.profiles(id), display_name text NOT NULL CHECK (char_length(btrim(display_name)) BETWEEN 1 AND 100), rating integer NOT NULL CHECK (rating BETWEEN 1 AND 5), comment text NOT NULL CHECK (char_length(btrim(comment)) BETWEEN 1 AND 2000), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.site_reviews TO anon,authenticated;
GRANT INSERT, UPDATE, DELETE ON public.site_reviews TO authenticated;
GRANT ALL ON public.site_reviews TO service_role;
ALTER TABLE public.site_reviews ENABLE ROW LEVEL SECURITY;
CREATE POLICY "reviews public read" ON public.site_reviews FOR SELECT TO anon,authenticated USING (true);
CREATE POLICY "reviews own insert" ON public.site_reviews FOR INSERT TO authenticated WITH CHECK (user_id=auth.uid());
CREATE POLICY "reviews own update" ON public.site_reviews FOR UPDATE TO authenticated USING (user_id=auth.uid()) WITH CHECK (user_id=auth.uid());
CREATE POLICY "reviews own delete" ON public.site_reviews FOR DELETE TO authenticated USING (user_id=auth.uid());
CREATE POLICY "works example public files" ON storage.objects FOR SELECT TO anon,authenticated USING (bucket_id='learning-works' AND EXISTS (SELECT 1 FROM public.course_examples e WHERE e.media_path=name));
CREATE POLICY "works private files read" ON storage.objects FOR SELECT TO authenticated USING (bucket_id='learning-works' AND ((storage.foldername(name))[1]=auth.uid()::text OR public.has_role(auth.uid(),'admin')));
CREATE POLICY "works own uploads" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id='learning-works' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY "works own removal" ON storage.objects FOR DELETE TO authenticated USING (bucket_id='learning-works' AND ((storage.foldername(name))[1]=auth.uid()::text OR public.has_role(auth.uid(),'admin')));